mapper.select:
select from lab_usage_record u join lab_reservation r on r.id = u.reservation_id and r.del_flag = '0' join lab_device d on d.id = u.device_id and d.del_flag = '0' where u.del_flag = '0'
and r.reservation_no = #{query.reservationNo}
and d.asset_no = #{query.assetNo}
and u.return_condition = #{query.returnCondition}
and u.checked_out_at >= #{query.checkedOutFrom}
and u.checked_out_at < #{query.checkedOutTo}
order by
r.reservation_no d.asset_no u.checked_out_at u.returned_at u.id
asc desc
